const body = $json.body ?? $json;
const revenue = Number(body.annual_revenue ?? 0);
const employees = Number(body.employee_count ?? 0);
const score = Math.min(100, Math.round((revenue / 500000) + (employees / 20) + (body.intent_signal ? 25 : 0)));
const segment = revenue >= 20000000 ? 'Enterprise' : revenue >= 5000000 ? 'Mid-Market' : 'SMB';
const region = body.region ?? 'Central';
const owner = `${region.slice(0, 2).toUpperCase()}-${segment === 'Enterprise' ? 'ENT' : segment === 'Mid-Market' ? 'MM' : 'SMB'}`;
const eventTimestamp = new Date().toISOString();
const leadId = body.lead_id ?? `LEAD-${Date.now()}`;
return [{ json: { ...body, lead_id: leadId, account_id: body.account_id ?? `ACC-${leadId}`, event_id: `${leadId}-${eventTimestamp}`, event_type: 'lead_routed', lifecycle_stage: score >= 70 ? 'mql' : 'lead', event_timestamp: eventTimestamp, score, segment, region, owner_id: owner, route_seconds: 0, is_duplicate: false } }];
